@if($googleMapsKey&&$selectedRoute)<script>
(g=>{var h,a,k,p='The Google Maps JavaScript API',c='google',l='importLibrary',q='__ib__',m=document,b=window;b=b[c]||(b[c]={});var d=b.maps||(b.maps={}),r=new Set,e=new URLSearchParams,u=()=>h||(h=new Promise(async(f,n)=>{await(a=m.createElement('script'));e.set('libraries',[...r]+'');for(k in g)e.set(k.replace(/[A-Z]/g,t=>'_'+t[0].toLowerCase()),g[k]);e.set('callback',c+'.maps.'+q);a.src=`https://maps.${c}apis.com/maps/api/js?`+e;d[q]=f;a.onerror=()=>h=n(Error(p+' could not load.'));m.head.append(a)}));d[l]?console.warn(p+' only loads once. Ignoring:',g):d[l]=(f,...n)=>r.add(f)&&u().then(()=>d[l](f,...n))})({key:@json($googleMapsKey),v:'weekly'});
async function initCoverageMap(){
    const [{Map},{AdvancedMarkerElement},{Route}]=await Promise.all([google.maps.importLibrary('maps'),google.maps.importLibrary('marker'),google.maps.importLibrary('routes')]);
    const points=@json($mapPoints),center=points[0]||{lat:13.0918,lng:-86.3538};
    const map=new Map(document.getElementById('coverage-map'),{center,zoom:13,mapId:@json(config('services.google_maps.map_id')),disableDefaultUI:true,zoomControl:true});
    const bounds=new google.maps.LatLngBounds(),info=new google.maps.InfoWindow();
    points.forEach(point=>{const position={lat:point.lat,lng:point.lng},pin=document.createElement('button');pin.type='button';pin.className=`grid h-9 w-9 place-items-center rounded-full border-2 border-white text-xs font-bold text-white shadow-lg ${point.status==='visited'?'bg-emerald-500':point.status==='not_found'?'bg-rose-400':'bg-indigo-500'}`;pin.textContent=point.position;pin.setAttribute('aria-label',`${point.position}. ${point.name}`);const marker=new AdvancedMarkerElement({map,position,content:pin,title:point.name});marker.addListener('click',()=>{const content=document.createElement('div'),name=document.createElement('strong'),address=document.createElement('small');content.style.padding='4px';name.textContent=point.name;address.textContent=point.address||'Sin dirección';content.append(name,document.createElement('br'),address);if(point.visited_at_label){const visit=document.createElement('small');visit.style.display='block';visit.style.marginTop='4px';visit.textContent=`${point.status_label} el ${point.visited_at_label}`;content.append(visit);}info.setContent(content);info.open({map,anchor:marker})});bounds.extend(position)});
    if(points.length>1){
        let distance=0,duration=0;
        try{
            for(let start=0;start<points.length-1;start+=24){const segment=points.slice(start,Math.min(points.length,start+25)),locations=segment.map(({lat,lng})=>({lat,lng})),response=await Route.computeRoutes({origin:locations[0],destination:locations.at(-1),intermediates:locations.slice(1,-1),travelMode:'DRIVING',optimizeWaypointOrder:false,fields:['path','distanceMeters','durationMillis']});const route=response.routes?.[0];if(!route)throw new Error('Google no devolvió un recorrido');route.createPolylines().forEach(polyline=>{polyline.setOptions({strokeColor:'#4f46e5',strokeOpacity:.85,strokeWeight:5});polyline.setMap(map)});distance+=route.distanceMeters||0;duration+=route.durationMillis||0}
            document.getElementById('route-distance').textContent=`${(distance/1000).toLocaleString('es-NI',{maximumFractionDigits:1})} km`;
            document.getElementById('route-duration').textContent=`${Math.max(1,Math.round(duration/60000))} min aprox.`;
        }catch(error){console.error(error);new google.maps.Polyline({map,path:points.map(({lat,lng})=>({lat,lng})),strokeColor:'#f59e0b',strokeOpacity:.75,strokeWeight:4,icons:[{icon:{path:'M 0,-1 0,1',strokeOpacity:1,scale:3},offset:'0',repeat:'14px'}]});document.getElementById('route-distance').textContent='Ruta vial no disponible';}
        map.fitBounds(bounds,48);
    }else if(points.length===1)map.setCenter(center);
}
initCoverageMap().catch(()=>document.getElementById('coverage-map').innerHTML='<div class="grid h-full place-items-center bg-rose-50 p-6 text-center text-sm text-rose-600">No se pudo cargar Google Maps. Revisa la clave, Maps JavaScript API y Routes API.</div>');
</script>@endif
